import * as THREE from 'three';
import {Brush,Evaluator,ADDITION,SUBTRACTION,INTERSECTION} from 'three-bvh-csg';
import {resolveShape,profileFor,validateProfile,newEntity} from './cad-data.js';
export function entityMatrix(entity){return new THREE.Matrix4().compose(new THREE.Vector3(...entity.position),new THREE.Quaternion().setFromEuler(new THREE.Euler(...entity.rotation.map(THREE.MathUtils.degToRad),'XYZ')),new THREE.Vector3(...entity.scale));}
export function geometryForShape(shape){const p=shape.params;let g;if(['box','rectangle','circle','polygon','extrusion'].includes(shape.type)){const points=profileFor(shape);validateProfile(points);const s=new THREE.Shape(points.map(([x,z])=>new THREE.Vector2(x,-z)));const height=shape.type==='box'?p.height:shape.type==='extrusion'?p.height:0;g=height?new THREE.ExtrudeGeometry(s,{depth:Math.abs(height),bevelEnabled:false,steps:1}):new THREE.ShapeGeometry(s);g.rotateX(-Math.PI/2);if(height<0)g.translate(0,height,0);}
else if(shape.type==='cylinder'){g=new THREE.CylinderGeometry(p.radius,p.radius,p.height,p.segments||32);g.translate(0,p.height/2,0);}
else if(shape.type==='sphere'){g=new THREE.SphereGeometry(p.radius,p.segments||32,Math.max(8,(p.segments||32)/2));g.translate(0,p.radius,0);}
else if(shape.type==='line')g=new THREE.BufferGeometry().setFromPoints(p.points.map(p=>new THREE.Vector3(...p)));
else if(shape.type==='pipe'){const curve=new THREE.CatmullRomCurve3(p.points.map(p=>new THREE.Vector3(...p)),false,'centripetal');g=new THREE.TubeGeometry(curve,Math.min(256,p.points.length*12),p.radius,p.segments||16,false);}
else if(shape.type==='mesh'){g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(p.vertices,3));g.computeVertexNormals();}
else throw Error('Unsupported geometry.');g.computeBoundingBox();return g;}
export function modelObject(cad,entity){const shape=resolveShape(cad,entity),geometry=geometryForShape(shape),object=shape.type==='line'?new THREE.Line(geometry,new THREE.LineBasicMaterial({color:entity.color})):new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({color:entity.color,roughness:.75,side:THREE.DoubleSide}));object.position.fromArray(entity.position);object.rotation.set(...entity.rotation.map(THREE.MathUtils.degToRad),'XYZ');object.scale.fromArray(entity.scale);object.castShadow=true;object.receiveShadow=true;object.userData={id:entity.id,kind:'cad'};return object;}
function reverseWinding(geometry){const a=geometry.getAttribute('position');for(let i=0;i<a.count;i+=3){const b=[a.getX(i+1),a.getY(i+1),a.getZ(i+1)];a.setXYZ(i+1,a.getX(i+2),a.getY(i+2),a.getZ(i+2));a.setXYZ(i+2,...b);}a.needsUpdate=true;geometry.computeVertexNormals();}
export function bakedGeometry(cad,entity){const base=geometryForShape(resolveShape(cad,entity)),geometry=base.index?base.toNonIndexed():base;const matrix=entityMatrix(entity);geometry.applyMatrix4(matrix);if(matrix.determinant()<0)reverseWinding(geometry);if(geometry!==base)base.dispose();return geometry;}
export function geometryData(geometry){const g=geometry.index?geometry.toNonIndexed():geometry,position=g.getAttribute('position');if(!position||position.count%3||position.count>100000)throw Error('Use a triangular model with at most 100,000 vertices.');const vertices=Array.from(position.array);if(g!==geometry)g.dispose();if(!vertices.every(v=>Number.isFinite(v)&&Math.abs(v)<=1000))throw Error('Model extent exceeds 1 km. Rescale the source model before importing.');return{type:'mesh',params:{vertices}};}
export function volume(geometry){const g=geometry.index?geometry.toNonIndexed():geometry,p=g.getAttribute('position');let sum=0;for(let i=0;i<p.count;i+=3){const a=new THREE.Vector3().fromBufferAttribute(p,i),b=new THREE.Vector3().fromBufferAttribute(p,i+1),c=new THREE.Vector3().fromBufferAttribute(p,i+2);sum+=a.dot(b.cross(c))/6;}if(g!==geometry)g.dispose();return Math.abs(sum);}
export function booleanEntity(cad,a,b,operation){if(!['union','subtract','intersect'].includes(operation))throw Error('Unknown solid operation.');if([a,b].some(e=>e.locked||['line','rectangle','circle','polygon','pipe'].includes(resolveShape(cad,e).type)))throw Error('Choose two unlocked closed solids. Open profiles and pipes cannot be boolean operands.');const ga=bakedGeometry(cad,a),gb=bakedGeometry(cad,b);if(!ga.getAttribute('normal'))ga.computeVertexNormals();if(!gb.getAttribute('normal'))gb.computeVertexNormals();const material=new THREE.MeshStandardMaterial(),aa=new Brush(ga,material),bb=new Brush(gb,material);aa.updateMatrixWorld();bb.updateMatrixWorld();const evaluator=new Evaluator();evaluator.attributes=['position','normal'];evaluator.useGroups=false;let result;try{result=evaluator.evaluate(aa,bb,{union:ADDITION,subtract:SUBTRACTION,intersect:INTERSECTION}[operation]);if(!result.geometry.getAttribute('position')?.count)throw Error('The result is empty. Check that the solids overlap.');const e=newEntity('mesh',a.floorId,geometryData(result.geometry).params);e.name=`${operation==='union'?'Union':operation==='subtract'?'Difference':'Intersection'} of ${a.name}`;e.color=a.color;return e;}finally{ga.dispose();gb.dispose();result?.geometry.dispose();material.dispose();}}
export async function importModel(file,floorId){if(file.size>12*1024*1024)throw Error('Use a model smaller than 12 MB.');const suffix=file.name.split('.').pop().toLowerCase();let object;if(suffix==='stl'){const {STLLoader}=await import('./vendor/loaders/STLLoader.js');object=new THREE.Mesh(new STLLoader().parse(await file.arrayBuffer()));}
else if(suffix==='obj'){const {OBJLoader}=await import('./vendor/loaders/OBJLoader.js');object=new OBJLoader().parse(await file.text());}
else if(suffix==='glb'){const {GLTFLoader}=await import('./vendor/loaders/GLTFLoader.js');const manager=new THREE.LoadingManager();manager.setURLModifier(url=>{if(!url.startsWith('data:')&&!url.startsWith('blob:'))throw Error('Only self-contained GLB models are supported.');return url;});const result=await new GLTFLoader(manager).parseAsync(await file.arrayBuffer(),'');object=result.scene;}
else throw Error('Choose a self-contained GLB, OBJ, or STL file.');object.updateMatrixWorld(true);const vertices=[];try{object.traverse(child=>{if(!child.isMesh)return;const source=child.geometry,geometry=source.index?source.toNonIndexed():source.clone();geometry.applyMatrix4(child.matrixWorld);for(const value of geometryData(geometry).params.vertices)vertices.push(value);geometry.dispose();if(vertices.length>300000)throw Error('The combined model exceeds 100,000 triangle vertices.');});if(!vertices.length)throw Error('The file contains no triangle meshes.');const e=newEntity('mesh',floorId,{vertices});e.name=file.name.replace(/\.[^.]+$/,'').slice(0,100)||'Imported model';return e;}finally{object.traverse(o=>{o.geometry?.dispose();const m=Array.isArray(o.material)?o.material:[o.material];m.forEach(m=>{if(m){for(const value of Object.values(m))if(value?.isTexture)value.dispose();m.dispose();}});});}}
export function exportDXF(floor,cad){const out=['0','SECTION','2','HEADER','9','$INSUNITS','70','6','0','ENDSEC','0','SECTION','2','ENTITIES'];const line=(a,b,layer)=>out.push('0','LINE','8',layer,'10',String(a[0]),'20',String(-a[1]),'30','0','11',String(b[0]),'21',String(-b[1]),'31','0');for(const w of floor.walls)line([w.x1,w.z1],[w.x2,w.z2],'WALLS');for(const e of cad.entities.filter(e=>e.floorId===floor.id&&e.visible&&cad.tags.find(t=>t.id===e.tagId)?.visible)){const shape=resolveShape(cad,e);let points,closed=true;if(shape.type==='line'){points=shape.params.points.map(p=>[p[0],p[2]]);closed=false;}else{try{points=profileFor(shape);}catch{continue;}}const matrix=entityMatrix(e),world=points.map(p=>new THREE.Vector3(p[0],0,p[1]).applyMatrix4(matrix)).map(p=>[p.x,p.z]);for(let i=1;i<world.length;i++)line(world[i-1],world[i],'MODELS');if(closed)line(world.at(-1),world[0],'MODELS');}out.push('0','ENDSEC','0','EOF');return out.join('\r\n');}
